491	.tooltip {
492	  display: inline-block;
493	  position: relative;
494	  cursor: help;
495	}
496	
497	.tooltip::after {
498	  content: attr(data-tooltip);
499	  position: absolute;
500	  bottom: 80%;
501	  left: 50%;
502	  transform: translateX(-50%);
503	  background: #082753;
504	  color: #fff;
505	  padding: 8px 12px;
506	  border-radius: 6px;
507	  font-size: 12px;
508	  white-space: normal;
509	  opacity: 0;
510	  pointer-events: none;
511	  transition: 0.25s ease;
512	  z-index: 9999;
513	  width: 200px;
514	  text-align: center;
515	}
516	
517	.tooltip:hover::after {
518	  opacity: 1;
519	  bottom: 90%;
520	}
521	
522	.tooltip::before {
523	  content: '';
524	  position: absolute;
525	  bottom: 71%;
526	  left: 50%;
527	  transform: translateX(-50%);
528	  border: 6px solid transparent;
529	  border-top-color: #082753;
530	  opacity: 0;
531	  transition: 0.25s ease;
532	}
533	
534	.tooltip:hover::before {
